  -- source id: 1
  (
    'de000001-0001-4000-8000-000000000001',
    'FDC — Reentry & Transition Services',
    'The Florida Department of Corrections coordinates statewide reentry planning, pre-release programming, and community transition services for people leaving FDC custody across all 67 counties. Reentry staff at the Tallahassee headquarters work with facility classification counselors, probation officers, and local nonprofits to connect returning citizens to housing, employment, MyACCESS benefits, and treatment before and after release. This office provides planning and referrals—not emergency shelter, cash assistance, or legal representation.',
    'El Departamento de Correcciones de Florida coordina la planificación estatal de reinserción, programación previa a la liberación y servicios de transición comunitaria para personas que salen de custodia FDC en los 67 condados. El personal de reinserción en Tallahassee trabaja con consejeros de clasificación, oficiales de probatoria y organizaciones locales para conectar a ciudadanos que regresan con vivienda, empleo, beneficios MyACCESS y tratamiento.',
    'c1000001-0001-4000-8000-000000000001',
    'Florida',
    'Leon',
    'Tallahassee',
    '501 South Calhoun Street',
    '850-488-5021',
    'https://www.fdc.myflorida.com/reentry',
    NULL,
    'State office Monday–Friday business hours',
    'Individuals in FDC custody preparing for release or under community supervision; community partners seeking FDC reentry engagement.',
    'Personas en custodia FDC que se preparan para la liberación o bajo supervisión comunitaria; aliados comunitarios que buscan coordinación de reinserción.',
    'Visit fdc.myflorida.com/reentry for program overview; coordinate through facility reentry staff and assigned probation officer after release.',
    'Visite fdc.myflorida.com/reentry; coordine con el personal de reinserción de la instalación y el oficial de probatoria asignado.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Pre-release planning', 'Community reentry coordination', 'Partner referrals', 'Reentry resource navigation', 'Supervision linkage'],
    ARRAY['statewide', 'reentry', 'FDC', 'DOC', 'pre-release', 'community-supervision'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 2
  (
    'de000001-0002-4000-8000-000000000001',
    'FDC — Probation & Parole Services',
    'FDC Probation and Parole Services supervises adults on felony probation, parole, and community control through circuit offices across Florida, connecting supervisees to employment, treatment, and housing resources as conditions of release. Probation officers coordinate with CareerSource Florida, DCF MyACCESS, local behavioral health providers, and reentry nonprofits in every county. Contact your assigned officer—not a walk-in benefits or emergency housing intake center.',
    'Servicios de Probatoria y Libertad Condicional de FDC supervisa adultos en probatoria por delito grave, libertad condicional y control comunitario a través de oficinas de circuito en Florida, conectando a supervisados con empleo, tratamiento y vivienda según condiciones de liberación. Los oficiales coordinan con CareerSource Florida, MyACCESS DCF y proveedores locales.',
    'c1000001-0016-4000-8000-000000000001',
    'Florida',
    'Leon',
    'Tallahassee',
    '501 South Calhoun Street',
    '850-488-5021',
    'https://www.fdc.myflorida.com/probation',
    NULL,
    'Circuit offices typically Monday–Friday business hours',
    'Adults under FDC probation, parole, or community control in Florida; report to assigned probation officer.',
    'Adultos bajo probatoria, libertad condicional o control comunitario de FDC en Florida; reporte al oficial de probatoria asignado.',
    'Find circuit office contacts at fdc.myflorida.com/probation; statewide information 850-488-5021.',
    'Encuentre contactos de oficinas de circuito en fdc.myflorida.com/probation; información estatal 850-488-5021.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Probation supervision', 'Parole reporting', 'Treatment referrals', 'Employment coordination', 'Reentry partner linkage'],
    ARRAY['statewide', 'probation-parole', 'FDC', 'parole', 'community-control', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 3
  (
    'de000001-0003-4000-8000-000000000001',
    'MyACCESS Florida',
    'MyACCESS Florida is the state''s official online portal for applying for and managing SNAP food assistance, Temporary Cash Assistance (TCA), and Florida Medicaid through the Department of Children and Families. Justice-involved Floridians can apply for health coverage and food support after release from FDC custody or county jails using the same account used by county DCF Family Resource Centers statewide. Online application and account management—not a crisis hotline or emergency shelter provider.',
    'MyACCESS Florida es el portal en línea oficial del estado para solicitar y administrar asistencia alimentaria SNAP, Asistencia Temporal en Efectivo (TCA) y Medicaid de Florida a través del Departamento de Niños y Familias. Los floridanos en reinserción pueden solicitar cobertura de salud y apoyo alimentario después de la liberación usando la misma cuenta que las oficinas DCF del condado.',
    'c1000001-0009-4000-8000-000000000001',
    'Florida',
    'Statewide',
    NULL,
    NULL,
    '850-300-4323',
    'https://myaccess.myflfamilies.com',
    NULL,
    'Online 24/7; county DCF office hours vary',
    'Florida residents meeting income and household requirements for Medicaid, SNAP, or TCA; criminal record generally not a barrier to Medicaid and SNAP.',
    'Residentes de Florida que cumplan requisitos de ingresos para Medicaid, SNAP o TCA; los antecedentes penales generalmente no son barrera para Medicaid y SNAP.',
    'Apply online at myaccess.myflfamilies.com; call 850-300-4323 for DCF Customer Call Center; visit county Family Resource Center for in-person help.',
    'Solicite en myaccess.myflfamilies.com; llame al 850-300-4323; visite el Centro de Recursos Familiares del condado.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Medicaid application', 'SNAP enrollment', 'TCA application', 'Benefits account management', 'Document upload'],
    ARRAY['statewide', 'benefits', 'Medicaid', 'SNAP', 'online', 'DCF', 'ACCESS', 'reentry'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 4
  (
    'de000001-0004-4000-8000-000000000001',
    'AHCA — Florida Medicaid',
    'The Agency for Health Care Administration administers Florida Medicaid managed care for eligible low-income Floridians through contracted health plans and managed medical assistance across all 67 counties. Returning citizens can enroll through MyACCESS Florida or county DCF offices to access primary care, behavioral health, and prescription coverage after release from FDC custody. AHCA is health coverage administration—not a walk-in clinic or emergency room.',
    'La Agencia para la Administración de Atención Médica administra la atención administrada de Medicaid de Florida para floridanos elegibles de bajos ingresos a través de planes de salud contratados en los 67 condados. Los ciudadanos que regresan pueden inscribirse a través de MyACCESS Florida para acceder a atención primaria y salud conductual. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0004-4000-8000-000000000001',
    'Florida',
    'Leon',
    'Tallahassee',
    '2727 Mahan Drive',
    '877-254-1055',
    'https://www.ahca.myflorida.com',
    NULL,
    'State office Monday–Friday business hours',
    'Florida residents meeting Medicaid income and categorical eligibility; enrollment through MyACCESS or DCF.',
    'Residentes de Florida que cumplan elegibilidad de ingresos de Medicaid; inscripción a través de MyACCESS o DCF.',
    'Apply at myaccess.myflfamilies.com; member services 877-254-1055; find your plan at ahca.myflorida.com.',
    'Solicite en myaccess.myflfamilies.com; servicios al miembro 877-254-1055; encuentre su plan en ahca.myflorida.com.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Medicaid enrollment', 'Health plan selection', 'Member services', 'Behavioral health plan navigation', 'Coverage verification'],
    ARRAY['statewide', 'healthcare', 'Medicaid', 'AHCA', 'insurance', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 5
  (
    'de000001-0005-4000-8000-000000000001',
    '211 Florida',
    '211 Florida is a free statewide information and referral service connecting residents to health and human services including housing, food, utilities, employment, and crisis support in all 67 Florida counties. United Way-supported navigators help callers find local programs by need and ZIP code through 211.org and by dialing 211 from any Florida phone. 211 Florida is a referral service—not a direct-service provider.',
    '211 Florida es un servicio gratuito de información y referencia estatal que conecta a residentes con servicios de salud y humanos incluyendo vivienda, alimentos, servicios públicos, empleo y apoyo en crisis en los 67 condados de Florida. Navegadores apoyados por United Way ayudan a encontrar programas locales por necesidad y código postal. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0001-4000-8000-000000000001',
    'Florida',
    'Statewide',
    NULL,
    NULL,
    '211',
    'https://www.211.org',
    NULL,
    'Available during published service hours; check 211.org',
    'Open to all Florida residents; no criminal-record restrictions stated.',
    'Abierto a todos los residentes de Florida; sin restricciones de antecedentes indicadas.',
    'Dial 211 from any Florida phone; search resources online at 211.org; text your ZIP code to 898-211.',
    'Marque 211 desde cualquier teléfono de Florida; busque recursos en 211.org; envíe su código postal al 898-211.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Information and referral', 'Crisis navigation', 'Housing referrals', 'Benefits navigation', 'Utility assistance referrals'],
    ARRAY['statewide', 'hotline', '211', 'referral-only', 'basic-needs'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 6
  (
    'de000001-0006-4000-8000-000000000001',
    'Florida Legal Services — Statewide Intake',
    'Florida Legal Services operates a statewide intake line connecting low-income Floridians—including returning citizens with civil legal needs after release from FDC custody—to regional legal aid offices for housing, benefits, family law, and expungement assistance. Intake specialists route callers to local programs such as Bay Area Legal Services, Community Legal Services of Mid-Florida, and Legal Services of Greater Miami. Civil legal aid—not criminal defense representation.',
    'Florida Legal Services opera una línea de admisión estatal que conecta a floridanos de bajos ingresos—incluidos ciudadanos que regresan con necesidades legales civiles después de la liberación de custodia FDC—a oficinas regionales de ayuda legal para vivienda, beneficios, derecho familiar y asistencia de eliminación de antecedentes. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0006-4000-8000-000000000001',
    'Florida',
    'Leon',
    'Tallahassee',
    '2425 Torrey Pines Drive',
    '850-385-7900',
    'https://www.floridalegal.org',
    NULL,
    'Monday–Friday business hours',
    'Low-income Florida residents with civil legal needs; income and case-type eligibility vary by regional program.',
    'Residentes de Florida de bajos ingresos con necesidades legales civiles; la elegibilidad varía según el programa regional.',
    'Call 850-385-7900 for statewide intake; visit floridalegal.org to find your regional legal aid office.',
    'Llame al 850-385-7900 para admisión estatal; visite floridalegal.org para encontrar su oficina regional.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Legal aid intake', 'Housing legal help', 'Benefits appeals', 'Family law referrals', 'Expungement guidance'],
    ARRAY['statewide', 'legal-aid', 'intake', 'civil', 'reentry', 'expungement'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
