  -- source id: 7
  (
    'de000001-0007-4000-8000-000000000001',
    'CareerSource Florida',
    'CareerSource Florida is the statewide workforce development network connecting job seekers—including justice-involved adults after FDC release—to WIOA-funded training, resume assistance, career coaching, and fair-chance employer navigation through 24 local CareerSource boards across all 67 counties. Returning citizens can register online and visit local career centers for employment services linked to DCF benefits and reentry nonprofits. Free core career services—not emergency cash or housing placement.',
    'CareerSource Florida es la red estatal de desarrollo laboral que conecta buscadores de empleo—incluidos adultos con antecedentes penales después de la liberación FDC—a capacitación WIOA, ayuda con currículum y navegación de empleo de segunda oportunidad a través de 24 juntas locales CareerSource en los 67 condados. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0003-4000-8000-000000000001',
    'Florida',
    'Statewide',
    'Tallahassee',
    '2002 Old St. Augustine Road',
    '850-245-4500',
    'https://careersourceflorida.com',
    NULL,
    'Local career center hours vary; online registration 24/7',
    'Open to Florida job seekers including justice-involved individuals; core CareerSource services are free.',
    'Abierto a buscadores de empleo de Florida incluidas personas con antecedentes penales; servicios básicos gratuitos.',
    'Register at careersourceflorida.com; call 850-245-4500; find your local board by county.',
    'Regístrese en careersourceflorida.com; llame al 850-245-4500; encuentre su junta local por condado.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Job search assistance', 'WIOA training referrals', 'Resume coaching', 'Fair-chance employment', 'Career planning'],
    ARRAY['statewide', 'employment', 'CareerSource', 'WIOA', 'fair-chance', 'reentry'],
