  -- source id: 8
  (
    'de000001-0008-4000-8000-000000000001',
    'Florida Division of Vocational Rehabilitation',
    'The Florida Division of Vocational Rehabilitation helps Floridians with disabilities—including justice-involved individuals with documented disabilities—prepare for, obtain, and retain employment through counseling, training, assistive technology, and job placement across 15 area offices statewide. VR counselors coordinate with CareerSource Florida, FDC reentry staff, and local employers for fair-chance hiring. Vocational rehabilitation—not emergency benefits or housing.',
    'La División de Rehabilitación Vocacional de Florida ayuda a floridanos con discapacidades—incluidas personas con antecedentes penales con discapacidades documentadas—a prepararse, obtener y mantener empleo a través de consejería, capacitación y colocación laboral en 15 oficinas de área en todo el estado. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0003-4000-8000-000000000001',
    'Florida',
    'Statewide',
    'Tallahassee',
    '2002 Old St. Augustine Road',
    '850-245-4200',
    'https://www.rehabworks.org',
    NULL,
    'Area offices Monday–Friday business hours',
    'Florida residents with physical or mental disabilities that create barriers to employment; justice-involved applicants with qualifying disabilities.',
    'Residentes de Florida con discapacidades físicas o mentales que crean barreras al empleo; solicitantes con antecedentes penales con discapacidades calificadas.',
    'Apply at rehabworks.org or call 850-245-4200; area offices serve all 67 counties.',
    'Solicite en rehabworks.org o llame al 850-245-4200; las oficinas de área sirven a los 67 condados.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Vocational counseling', 'Job placement', 'Training referrals', 'Assistive technology', 'Employer coordination'],
    ARRAY['statewide', 'employment', 'vocational-rehab', 'disability', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 9
  (
    'de000001-0009-4000-8000-000000000001',
    'Florida Department of Veterans'' Affairs',
    'The Florida Department of Veterans'' Affairs helps veterans and their families access federal VA benefits, state veterans preference in hiring, and county veterans service offices across all 67 counties. Justice-involved veterans leaving FDC custody can connect to VA healthcare, disability compensation, and housing programs through FDVA benefits counselors. Veterans benefits navigation—not emergency shelter or general population cash assistance.',
    'El Departamento de Asuntos de Veteranos de Florida ayuda a veteranos y sus familias a acceder a beneficios federales VA, preferencia de veteranos estatales en contratación y oficinas de servicios para veteranos del condado en los 67 condados. Los veteranos con antecedentes penales pueden conectarse con atención médica VA y programas de vivienda. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0014-4000-8000-000000000001',
    'Florida',
    'Pinellas',
    'Bay Pines',
    '9500 Bay Pines Boulevard',
    '727-319-7440',
    'https://www.floridavets.org',
    NULL,
    'County VSO offices Monday–Friday; state office business hours',
    'Florida veterans, service members, and eligible family members; DD-214 or military service documentation required.',
    'Veteranos de Florida, miembros del servicio y familiares elegibles; se requiere DD-214 o documentación de servicio militar.',
    'Find your county veterans service officer at floridavets.org; call 727-319-7440 for state headquarters.',
    'Encuentre su oficial de servicios para veteranos del condado en floridavets.org; llame al 727-319-7440.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['VA benefits counseling', 'Disability claims help', 'Healthcare enrollment', 'State hiring preference', 'Housing referrals'],
    ARRAY['statewide', 'veterans', 'VA', 'benefits', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
