  (
    'de000001-0010-4000-8000-000000000001',
    'FLHSMV — Driver Licenses & ID',
    'The Florida Department of Highway Safety and Motor Vehicles issues driver licenses, state identification cards, and driving records through tax collector and driver license service centers in all 67 counties. Returning citizens reestablishing identity after FDC release can obtain REAL ID-compliant credentials with required documents listed at flhsmv.gov. FLHSMV issues credentials—not probation reporting or benefits enrollment.',
    'El Departamento de Seguridad de Carreteras y Vehículos Motorizados de Florida emite licencias de conducir, tarjetas de identificación estatal y registros de conducción a través de centros de servicio en los 67 condados. Los ciudadanos que regresan pueden obtener credenciales compatibles con REAL ID con los documentos requeridos en flhsmv.gov. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0008-4000-8000-000000000001',
    'Florida',
    'Leon',
    'Tallahassee',
    '2900 Apalachee Parkway',
    '850-617-2000',
    'https://www.flhsmv.gov',
    NULL,
    'Service center hours vary by county',
    'Florida residents meeting identity and lawful presence documentation requirements for driver license or ID card.',
    'Residentes de Florida que cumplan requisitos de documentación de identidad y presencia legal para licencia o tarjeta de identificación.',
    'Schedule appointments at flhsmv.gov/locations; bring required documents; tax collector offices vary by county.',
    'Programe citas en flhsmv.gov/locations; traiga documentos requeridos; las oficinas del recaudador varían por condado.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Driver license issuance', 'State ID cards', 'Driving records', 'REAL ID credentials', 'Appointment scheduling'],
    ARRAY['statewide', 'id-documentation', 'DMV', 'driver-license', 'REAL-ID', 'reentry'],
