  (
    'de000001-0011-4000-8000-000000000001',
    'Florida Department of Health — Vital Records',
    'The Florida Department of Health Bureau of Vital Statistics issues certified birth certificates, death certificates, and marriage records needed for MyACCESS Medicaid enrollment, FLHSMV identification, and employment background checks after release from FDC custody. Orders can be placed online, by mail, or in person at county health departments statewide. Vital records issuance—not clinical healthcare or benefits intake.',
    'La Oficina de Estadísticas Vitales del Departamento de Salud de Florida emite certificados de nacimiento, defunción y matrimonio certificados necesarios para inscripción en Medicaid MyACCESS, identificación FLHSMV y verificaciones de antecedentes laborales después de la liberación de custodia FDC. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0008-4000-8000-000000000001',
    'Florida',
    'Duval',
    'Jacksonville',
    '1217 North Pearl Street',
    '904-359-6900',
    'https://www.floridahealth.gov/certificates',
    NULL,
    'Online 24/7; county health department business hours',
    'Individuals with legal right to request vital records per Florida statute; identity verification required.',
    'Personas con derecho legal a solicitar registros vitales según la ley de Florida; se requiere verificación de identidad.',
    'Order online at floridahealth.gov/certificates; processing times vary; county health departments accept walk-in requests.',
    'Ordene en línea en floridahealth.gov/certificates; los tiempos de procesamiento varían; los departamentos de salud del condado aceptan solicitudes presenciales.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Birth certificate orders', 'Death certificate orders', 'Marriage records', 'Online ordering', 'Identity verification guidance'],
