  (
    'de000001-0012-4000-8000-000000000001',
    '988 Suicide & Crisis Lifeline — Florida',
    'The 988 Suicide and Crisis Lifeline provides free, confidential 24/7 support for people in mental health crisis, emotional distress, or suicidal thoughts across Florida including justice-involved individuals and families during reentry. Florida''s 988 network connects callers to local crisis centers with mobile crisis teams and referrals to community behavioral health providers. Crisis support and referral—not housing placement or legal representation.',
    'La Línea de Crisis y Prevención del Suicidio 988 proporciona apoyo gratuito y confidencial 24/7 para personas en crisis de salud mental, angustia emocional o pensamientos suicidas en Florida incluidas personas con antecedentes penales y familias durante la reinserción. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0015-4000-8000-000000000001',
    'Florida',
    'Statewide',
    NULL,
    NULL,
    '988',
    'https://988lifeline.org',
    NULL,
    '24/7',
    'Open to anyone in crisis; no insurance or criminal-record restrictions.',
    'Abierto a cualquier persona en crisis; sin restricciones de seguro ni antecedentes penales.',
    'Dial or text 988; chat at 988lifeline.org; veterans press 1; Spanish services available.',
    'Marque o envíe mensaje al 988; chat en 988lifeline.org; veteranos presione 1; servicios en español disponibles.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Crisis counseling', 'Suicide prevention', 'Mobile crisis referrals', 'Emotional support', 'Warm handoffs'],
