  (
    'de000001-0013-4000-8000-000000000001',
    'SAMHSA National Helpline',
    'The SAMHSA National Helpline is a free, confidential 24/7 treatment referral service connecting Floridians—including returning citizens with substance use disorders—to local detox, outpatient, medication-assisted treatment, and recovery support providers across all 67 counties. Specialists help callers find Florida-licensed programs accepting Medicaid and sliding-fee care. Referral service—not direct treatment or emergency housing.',
    'La Línea Nacional de SAMHSA es un servicio gratuito y confidencial de referencia a tratamiento 24/7 que conecta a floridanos—incluidos ciudadanos que regresan con trastornos por uso de sustancias—a proveedores locales de desintoxicación, tratamiento ambulatorio y apoyo en recuperación en los 67 condados. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0005-4000-8000-000000000001',
    'Florida',
    'Statewide',
    NULL,
    NULL,
    '1-800-662-4357',
    'https://www.samhsa.gov/find-help/national-helpline',
    NULL,
    '24/7',
    'Open to anyone seeking substance use treatment information; no insurance required to call.',
    'Abierto a cualquier persona que busque información sobre tratamiento de uso de sustancias; no se requiere seguro para llamar.',
    'Call 1-800-662-HELP (4357); TTY 1-800-487-4889; Spanish-language support available.',
    'Llame al 1-800-662-HELP (4357); TTY 1-800-487-4889; soporte en español disponible.',
    ARRAY[]::TEXT[],
