  -- source id: 14
  (
    'de000001-0014-4000-8000-000000000001',
    'FindTreatment.gov',
    'FindTreatment.gov is SAMHSA''s searchable directory of licensed substance use treatment facilities across Florida, allowing returning citizens and families to filter by location, treatment type, payment options including Medicaid, and services such as outpatient, residential, and medication-assisted treatment. The tool supplements local referrals from FDC probation officers, courts, and Florida community behavioral health providers. Online directory—not a crisis hotline.',
    'FindTreatment.gov es el directorio buscable de SAMHSA de instalaciones de tratamiento de uso de sustancias con licencia en Florida, permitiendo a ciudadanos que regresan y familias filtrar por ubicación, tipo de tratamiento, opciones de pago incluido Medicaid y servicios ambulatorios o residenciales. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
    'c1000001-0005-4000-8000-000000000001',
    'Florida',
    'Statewide',
    NULL,
    NULL,
    '1-800-662-4357',
    'https://findtreatment.gov',
    NULL,
    'Online 24/7',
    'Open to anyone seeking treatment facility information; facility admission criteria vary.',
    'Abierto a cualquier persona que busque información de instalaciones de tratamiento; los criterios de admisión varían.',
    'Search by ZIP code at findtreatment.gov; call SAMHSA helpline 1-800-662-4357 for navigator help.',
