    'Florida Rights Restoration Coalition',
    'Florida Rights Restoration Coalition advocates for returning citizens and helps eligible Floridians restore voting rights and navigate civic reintegration after felony convictions. Staff connect justice-involved adults from FDC custody and Orange County jails to MyACCESS benefits, CareerSource employment, and local reentry partners across Orlando / Orange County. Direct program services—not emergency cash assistance or a general probation reporting office unless noted.',
    'Florida Rights Restoration Coalition aboga por ciudadanos que regresan y ayuda a floridanos elegibles a restaurar derechos de voto y navegar la reintegración cívica después de condenas por delito grave. El personal conecta a adultos con antecedentes penales de custodia FDC y cárceles del condado Orange con beneficios MyACCESS, empleo CareerSource y aliados locales de reinserción en Orlando / Orange County.',
