    'de000001-0020-4000-8000-000000000001',
    'Florida Office of the Public Defender — Civil Legal Referrals',
    'While Florida public defenders handle criminal defense, the statewide public defender system publishes civil legal referral guides connecting indigent clients after case closure—including returning citizens—to regional legal aid for eviction defense, benefits appeals, and record-sealing resources. Contact your regional legal aid office through Florida Legal Services intake for civil matters after criminal representation ends. Criminal defense during active cases; civil referrals after closure.',
