  (
    'de000001-0315-4000-8000-000000000001',
    'Bridges of America',
    'Bridges of America is Florida''s largest private provider of FDC-contracted substance abuse treatment and community reentry programming, operating residential treatment and work-release bridge centers across the state for justice-involved adults preparing to transition from incarceration. The Orlando headquarters coordinates referrals to bridge centers in Gainesville, Jacksonville, Bradenton, Lake City, Cocoa, and Pompano Beach—not a walk-in emergency shelter or general probation office.',
    'Bridges of America es el mayor proveedor privado de Florida de tratamiento de abuso de sustancias contratado por FDC y programación de reinserción comunitaria, operando centros puente de tratamiento residencial y liberación condicional de trabajo en todo el estado para adultos con antecedentes penales que se preparan para la transición desde la encarcelación. La sede de Orlando coordina referencias a centros puente en Gainesville, Jacksonville, Bradenton, Lake City, Cocoa y Pompano Beach—no es refugio de emergencia ni oficina general de libertad condicional.',
    'c1000001-0017-4000-8000-000000000001',
    'Florida',
    'Orange',
    'Orlando',
    '2001 Mercy Drive',
    '407-218-4800',
    'https://bridgesinternational.net',
    NULL,
    'Monday–Friday business hours',
    'Justice-involved adults in FDC custody referred to Bridges treatment or work-release programs; family inquiries welcome by phone.',
    'Adultos con antecedentes penales en custodia FDC referidos a programas de tratamiento o liberación condicional de trabajo de Bridges; consultas familiares por teléfono.',
    'Call 407-218-4800; program placement is through FDC classification and sentencing.',
