  (
    'de000001-0316-4000-8000-000000000001',
    'Florida Supportive Housing Coalition',
    'Florida Supportive Housing Coalition connects returning citizens to supportive housing providers statewide. Staff connect justice-involved adults from FDC custody and Leon County jails to MyACCESS benefits, CareerSource employment, and local reentry partners across Tallahassee / Leon County. Direct program services—not emergency cash assistance or a general probation reporting office unless noted.',
    'La Coalición de Vivienda de Apoyo de Florida conecta a ciudadanos que regresan con proveedores de vivienda de apoyo en todo el estado. El personal conecta a adultos con antecedentes penales de custodia FDC y cárceles del condado Leon con beneficios MyACCESS, empleo CareerSource y aliados locales de reinserción en Tallahassee / Leon County. Contact the program directly to confirm current hours, eligibility, and intake requirements before visiting in person.',
