  (
    'de000001-0323-4000-8000-000000000001',
    'CareerSource Central Florida — Osceola County',
    'CareerSource Central Florida — Osceola County serves justice-involved adults and families rebuilding stability after incarceration in Osceola County. CareerSource Central Florida serves Osceola County with free career services linking returning citizens to training, job placement, and MyACCESS benefits navigation partners. Staff connect participants to MyACCESS benefits, local healthcare, and reentry partners—not emergency cash or probation reporting unless noted. Staff help justice-involved job seekers build work history, remove record-related barriers, and connect to fair-chance employers in the region. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'CareerSource Central Florida — Osceola County sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Osceola. El personal ayuda a quienes buscan empleo con antecedentes penales a construir historial laboral, reducir barreras por antecedentes y conectarse con empleadores de segunda oportunidad. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
