    'de000001-0324-4000-8000-000000000001',
    'AdventHealth Kissimmee (serves Osceola County)',
    'AdventHealth Kissimmee (serves Osceola County) serves justice-involved adults and families rebuilding stability after incarceration in Osceola County. AdventHealth Kissimmee provides emergency and primary care for Osceola County residents including uninsured and Medicaid patients such as returning citizens establishing medical care. Staff connect participants to MyACCESS benefits, local healthcare, and reentry partners—not emergency cash or probation reporting unless noted. Services are available on a sliding fee or Medicaid basis for eligible patients; bring ID and release paperwork when establishing care after incarceration. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'AdventHealth Kissimmee (serves Osceola County) sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Osceola. Los servicios están disponibles con tarifa móvil o Medicaid para pacientes elegibles; lleve identificación y documentos de liberación al establecer atención después de la encarcelación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
