    'de000001-0325-4000-8000-000000000001',
    'CareerSource Central Florida — Seminole County',
    'CareerSource Central Florida — Seminole County is a statewide or regional referral resource for Floridians affected by the criminal justice system. CareerSource Central Florida Seminole location connects justice-involved job seekers to WIOA career coaching, training, and fair-chance employer referrals across Sanford and Seminole County. Staff connect participants to MyACCESS benefits, local healthcare, and reentry partners—not emergency cash or probation reporting unless noted. Users can search by location, service type, or need to find active providers in Seminole County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'CareerSource Central Florida — Seminole County es un recurso de referencia estatal o regional para floridanos afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en condado de Seminole. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
